// The corpus and the window are the ones the render benchmarks already use:
// simulated alignments over a 250 kb slice of hg19 chr22 (`chr22_mask`), at 20x
// / 200x / 1000x, short reads (wgsim) and long (pbsim), regenerated by
// ../shell/generate_alignments.sh. Reusing them means the parse numbers and the
// render numbers describe the same files.
import { readFileSync } from 'node:fs'
import { fileURLToPath } from 'node:url'

export const ROOT = fileURLToPath(new URL('../../', import.meta.url))

export const REF = 'chr22_mask'
export const START = 124_000
export const END = 143_000

export interface Case {
  label: string
  file: string
  /** records the window holds, asserted by equivalence.test.ts */
  records?: number
}

const COVERAGES = ['20x', '200x', '1000x'] as const
const KINDS = ['shortread', 'longread'] as const

function corpus(ext: string): Case[] {
  return COVERAGES.flatMap(cov =>
    KINDS.map(kind => ({
      label: `${cov} ${kind}`,
      file: `${ROOT}${cov}.${kind}.${ext}`,
    })),
  )
}

export const BAM_CASES = corpus('bam')
export const CRAM_CASES = corpus('cram')
export const BW_CASES = corpus('bw')

// hg19mod.fa is one contig, so the whole reference is small enough to hold as a
// string and answer seqFetch from memory. Doing it here rather than through an
// indexed-fasta reader keeps a second library out of the CRAM measurement.
let refSeq: string | undefined

export function reference(): string {
  if (refSeq === undefined) {
    const text = readFileSync(`${ROOT}hg19mod.fa`, 'utf8')
    refSeq = text.slice(text.indexOf('\n') + 1).replaceAll('\n', '')
  }
  return refSeq
}

/** CRAM's seqFetch contract is 1-based and inclusive on both ends. */
export const seqFetch = async (_seqId: number, start: number, end: number) =>
  reference().slice(start - 1, end)

// cram-js v1.7.1 defaults fetchSizeLimit to 3 MB and throws past it, which every
// long-read window here exceeds. JBrowse 2 never ran that default: its
// CramAdapter set `fetchSizeLimit: 200_000_000` with the comment "just make this
// a large size to avoid hitting it". Passing the same value reproduces what
// JBrowse actually ran rather than a limit no user of it ever hit. The current
// release has no such limit, so this option applies only to the old side.
export const OLD_CRAM_OPTS = { fetchSizeLimit: 200_000_000 }

export function bytes(file: string) {
  return readFileSync(file).byteLength
}
